    {
      "name": "one_le_finprod",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Sort u_4} {M : Type u_7} [inst : CommMonoidWithZero M] [inst_1 : Preorder M] [ZeroLEOneClass M] [PosMulMono M]\n  {f : α → M}, (∀ (i : α), 1 ≤ f i) → 1 ≤ ∏ᶠ (i : α), f i"
    },
    {
      "name": "Finset.one_le_prod'",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {N : Type u_5} [inst : CommMonoid N] [inst_1 : PartialOrder N] {f : ι → N} {s : Finset ι}\n  [MulLeftMono N], (∀ i ∈ s, 1 ≤ f i) → 1 ≤ ∏ i ∈ s, f i"
    },
    {
      "name": "Fintype.one_le_prod",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} [inst : Fintype ι] [inst_1 : CommMonoid M] [inst_2 : PartialOrder M] [MulLeftMono M]\n  {f : ι → M}, 1 ≤ f → 1 ≤ ∏ i, f i"
    },
    {
      "name": "Multiset.one_le_prod",
      "module_name": "Mathlib.Algebra.Order.BigOperators.GroupWithZero.Multiset",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommMonoidWithZero R] [inst_1 : PartialOrder R] [ZeroLEOneClass R] [PosMulMono R]\n  {s : Multiset R}, (∀ (a : R), a ∈ s → 1 ≤ a) → 1 ≤ s.prod"
    },
    {
      "name": "Fintype.one_lt_prod_iff_of_one_le",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} [inst : Fintype ι] [inst_1 : CommMonoid M] [inst_2 : PartialOrder M]\n  [IsOrderedCancelMonoid M] {f : ι → M}, 1 ≤ f → (1 < ∏ i, f i ↔ 1 < f)"
    }
  ]
}
